*** Begin Patch
*** Add File: /workspace/submission/infra/main.tf
+terraform {
+  required_providers {
+    aws = { source = "hashicorp/aws", version = ">= 5.80, < 6.0" }
+  }
+  backend "local" { path = "terraform.tfstate" }
+}
+
+variable "config" { type = map(string) }
+locals {
+  c = var.config
+  p = local.c.resource_prefix
+  region = local.c.region
+  endpoint = local.c.aws_endpoint_url
+  account = "000000000000"
+  roles = toset(["ecs_execution", "ecs_task", "projector", "relay", "archiver", "scheduler"])
+  key_roles = {
+    database = ["relay", "archiver"]
+    messaging = ["ecs_task", "projector", "relay"]
+    projection = ["ecs_task", "projector"]
+    audit = ["archiver"]
+  }
+  role_arns = { for r in local.roles : r => "arn:aws:iam::${local.account}:role/${local.p}-${r}" }
+  worker_arns = { for r in ["projector", "relay", "archiver"] : r => "arn:aws:lambda:${local.region}:${local.account}:function:${local.p}-${r}" }
+}
+provider "aws" {
+  region = local.region
+  access_key = "test"
+  secret_key = "test"
+  skip_credentials_validation = true
+  skip_metadata_api_check = true
+  skip_requesting_account_id = true
+  s3_use_path_style = true
+  default_tags { tags = { ClearLedgerDeployment = local.p } }
+  endpoints {
+    ec2 = local.endpoint
+    elbv2 = local.endpoint
+    ecs = local.endpoint
+    rds = local.endpoint
+    dynamodb = local.endpoint
+    elasticache = local.endpoint
+    s3 = local.endpoint
+    sqs = local.endpoint
+    lambda = local.endpoint
+    scheduler = local.endpoint
+    cognitoidp = local.endpoint
+    iam = local.endpoint
+    kms = local.endpoint
+    cloudwatchlogs = local.endpoint
+    sts = local.endpoint
+  }
+}
+resource "aws_vpc" "main" {
+  cidr_block = "10.42.0.0/16"
+  enable_dns_support = true
+  enable_dns_hostnames = true
+  tags = { Name = "${local.p}-vpc" }
+}
+resource "aws_subnet" "public" {
+  count = 2
+  vpc_id = aws_vpc.main.id
+  cidr_block = "10.42.${count.index}.0/24"
+  availability_zone = "${local.region}${["a", "b"][count.index]}"
+  map_public_ip_on_launch = true
+  tags = { Name = "${local.p}-public-${count.index}" }
+}
+resource "aws_subnet" "private" {
+  count = 2
+  vpc_id = aws_vpc.main.id
+  cidr_block = "10.42.${count.index + 10}.0/24"
+  availability_zone = "${local.region}${["a", "b"][count.index]}"
+  map_public_ip_on_launch = false
+  tags = { Name = "${local.p}-private-${count.index}" }
+}
+resource "aws_internet_gateway" "main" {
+  vpc_id = aws_vpc.main.id
+  tags = { Name = "${local.p}-igw" }
+}
+resource "aws_route_table" "public" {
+  vpc_id = aws_vpc.main.id
+  route {
+    cidr_block = "0.0.0.0/0"
+    gateway_id = aws_internet_gateway.main.id
+  }
+  tags = { Name = "${local.p}-public" }
+}
+resource "aws_route_table" "private" {
+  vpc_id = aws_vpc.main.id
+  route = []
+  tags = { Name = "${local.p}-private" }
+}
+resource "aws_route_table_association" "public" {
+  count = 2
+  subnet_id = aws_subnet.public[count.index].id
+  route_table_id = aws_route_table.public.id
+}
+resource "aws_route_table_association" "private" {
+  count = 2
+  subnet_id = aws_subnet.private[count.index].id
+  route_table_id = aws_route_table.private.id
+}
+resource "aws_security_group" "alb" {
+  name = "${local.p}-alb"
+  vpc_id = aws_vpc.main.id
+  ingress {
+    from_port = 80
+    to_port = 80
+    protocol = "tcp"
+    cidr_blocks = ["0.0.0.0/0"]
+  }
+  egress {
+    from_port = 8080
+    to_port = 8080
+    protocol = "tcp"
+    cidr_blocks = [aws_vpc.main.cidr_block]
+  }
+}
+resource "aws_security_group" "ecs" {
+  name = "${local.p}-ecs"
+  vpc_id = aws_vpc.main.id
+  ingress {
+    from_port = 8080
+    to_port = 8080
+    protocol = "tcp"
+    security_groups = [aws_security_group.alb.id]
+  }
+  egress {
+    from_port = 0
+    to_port = 0
+    protocol = "-1"
+    cidr_blocks = ["0.0.0.0/0"]
+  }
+}
+resource "aws_security_group" "store" {
+  for_each = { rds = 5432, valkey = 6379 }
+  name = "${local.p}-${each.key}"
+  vpc_id = aws_vpc.main.id
+  ingress {
+    from_port = each.value
+    to_port = each.value
+    protocol = "tcp"
+    cidr_blocks = [aws_vpc.main.cidr_block]
+  }
+  egress = []
+}
+resource "aws_kms_key" "key" {
+  for_each = local.key_roles
+  description = "${local.p}-${each.key}"
+  enable_key_rotation = true
+  is_enabled = true
+  deletion_window_in_days = 10
+  tags = { ClearLedgerKeyUsage = each.key, Name = "${local.p}-${each.key}" }
+  policy = jsonencode({ Version = "2012-10-17", Statement = [
+    { Sid = "RootAdministration", Effect = "Allow", Principal = { AWS = "arn:aws:iam::${local.account}:root" }, Action = "kms:*", Resource = "*" },
+    { Sid = "WorkloadUsage", Effect = "Allow", Principal = { AWS = [for r in each.value : local.role_arns[r]] }, Action = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"], Resource = "*" },
+    { Sid = "ProtectKeys", Effect = "Deny", Principal = { AWS = values(local.role_arns) }, Action = ["kms:DisableKey", "kms:ScheduleKeyDeletion"], Resource = "*" },
+    { Sid = "IsolateKeys", Effect = "Deny", Principal = { AWS = [for r in local.roles : local.role_arns[r] if !contains(each.value, r)] }, Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = "*" }
+  ] })
+  depends_on = [aws_iam_role.role]
+}
+resource "aws_kms_alias" "key" {
+  for_each = local.key_roles
+  name = "alias/${local.p}-${each.key}"
+  target_key_id = aws_kms_key.key[each.key].key_id
+}
+resource "aws_cloudwatch_log_group" "log" {
+  for_each = { api = "api", projector = "projector", relay = "outbox-relay", archiver = "audit-archiver" }
+  name = "/clearledger/${local.p}/${each.value}"
+  retention_in_days = 14
+}
+resource "aws_db_subnet_group" "main" {
+  name = "${local.p}-database"
+  subnet_ids = aws_subnet.private[*].id
+}
+resource "aws_db_instance" "main" {
+  identifier = "${local.p}-database"
+  engine = "postgres"
+  engine_version = "16.3"
+  instance_class = "db.t4g.micro"
+  allocated_storage = 20
+  db_name = local.c.db_name
+  username = local.c.db_username
+  password = local.c.db_password
+  storage_encrypted = true
+  kms_key_id = aws_kms_key.key["database"].arn
+  publicly_accessible = false
+  skip_final_snapshot = true
+  db_subnet_group_name = aws_db_subnet_group.main.name
+  vpc_security_group_ids = [aws_security_group.store["rds"].id]
+  apply_immediately = true
+  backup_retention_period = 7
+}
+resource "aws_dynamodb_table" "main" {
+  name = "${local.p}-projections"
+  billing_mode = "PAY_PER_REQUEST"
+  hash_key = "PK"
+  range_key = "SK"
+  dynamic "attribute" {
+    for_each = toset(["PK", "SK", "GSI1PK", "GSI1SK"])
+    content {
+      name = attribute.value
+      type = "S"
+    }
+  }
+  global_secondary_index {
+    name = "AccountIndex"
+    hash_key = "GSI1PK"
+    range_key = "GSI1SK"
+    projection_type = "ALL"
+  }
+  point_in_time_recovery { enabled = true }
+  server_side_encryption {
+    enabled = true
+    kms_key_arn = aws_kms_key.key["projection"].arn
+  }
+}
+resource "aws_elasticache_subnet_group" "main" {
+  name = "${local.p}-cache"
+  subnet_ids = aws_subnet.private[*].id
+}
+resource "aws_elasticache_replication_group" "main" {
+  replication_group_id = "${local.p}-cache"
+  description = "${local.p} projection cache"
+  engine = "valkey"
+  engine_version = "8.0"
+  node_type = "cache.t4g.micro"
+  num_cache_clusters = 1
+  port = 6379
+  subnet_group_name = aws_elasticache_subnet_group.main.name
+  security_group_ids = [aws_security_group.store["valkey"].id]
+  transit_encryption_enabled = false
+  at_rest_encryption_enabled = false
+  apply_immediately = true
+}
+resource "aws_s3_bucket" "audit" {
+  bucket = "${local.p}-audit"
+  force_destroy = true
+}
+resource "aws_s3_bucket_versioning" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  versioning_configuration { status = "Enabled" }
+}
+resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  rule {
+    apply_server_side_encryption_by_default {
+      sse_algorithm = "aws:kms"
+      kms_master_key_id = aws_kms_key.key["audit"].arn
+    }
+  }
+}
+resource "aws_s3_bucket_public_access_block" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  block_public_acls = true
+  block_public_policy = true
+  ignore_public_acls = true
+  restrict_public_buckets = true
+}
+resource "aws_sqs_queue" "dlq" {
+  name = "${local.p}-dlq"
+  kms_master_key_id = aws_kms_key.key["messaging"].arn
+  message_retention_seconds = 1209600
+}
+resource "aws_sqs_queue" "main" {
+  name = "${local.p}-events"
+  kms_master_key_id = aws_kms_key.key["messaging"].arn
+  visibility_timeout_seconds = 3
+  receive_wait_time_seconds = 2
+  message_retention_seconds = 172800
+  redrive_policy = jsonencode({ deadLetterTargetArn = aws_sqs_queue.dlq.arn, maxReceiveCount = 4 })
+}
+resource "aws_cognito_user_pool" "main" { name = "${local.p}-auth" }
+resource "aws_cognito_resource_server" "main" {
+  identifier = "clearledger"
+  name = "${local.p}-scopes"
+  user_pool_id = aws_cognito_user_pool.main.id
+  dynamic "scope" {
+    for_each = toset(["read", "write", "admin"])
+    content {
+      scope_name = scope.value
+      scope_description = "ClearLedger ${scope.value}"
+    }
+  }
+}
+resource "aws_cognito_user_pool_client" "client" {
+  for_each = toset(["read", "write", "admin"])
+  name = "${local.p}-${each.key}"
+  user_pool_id = aws_cognito_user_pool.main.id
+  generate_secret = true
+  allowed_oauth_flows_user_pool_client = true
+  allowed_oauth_flows = ["client_credentials"]
+  allowed_oauth_scopes = ["clearledger/${each.key}"]
+  depends_on = [aws_cognito_resource_server.main]
+}
*** Add File: /workspace/submission/infra/iam.tf
+resource "aws_iam_role" "role" {
+  for_each = local.roles
+  name = "${local.p}-${each.key}"
+  tags = { ClearLedgerRole = each.key }
+  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{
+    Effect = "Allow", Action = "sts:AssumeRole", Principal = { Service = startswith(each.key, "ecs_") ? "ecs-tasks.amazonaws.com" : each.key == "scheduler" ? "scheduler.amazonaws.com" : "lambda.amazonaws.com" }
+  }] })
+}
+locals {
+  queues = [aws_sqs_queue.main.arn, aws_sqs_queue.dlq.arn]
+  ddb = [aws_dynamodb_table.main.arn, "${aws_dynamodb_table.main.arn}/index/AccountIndex"]
+  s3 = [aws_s3_bucket.audit.arn, "${aws_s3_bucket.audit.arn}/*"]
+  sqs_actions = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
+  ddb_actions = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
+  s3_actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
+  role_log = { ecs_execution = "api", ecs_task = "api", projector = "projector", relay = "relay", archiver = "archiver", scheduler = "none" }
+  key_arns = [for k in aws_kms_key.key : k.arn]
+}
+resource "aws_iam_role_policy" "canonical" {
+  for_each = local.roles
+  name = "${local.p}-canonical"
+  role = aws_iam_role.role[each.key].id
+  policy = jsonencode({ Version = "2012-10-17", Statement = concat(
+    [{ Effect = "Deny", Action = ["kms:DisableKey", "kms:ScheduleKeyDeletion"], Resource = local.key_arns }],
+    [{ Effect = "Deny", Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = [for k, rs in local.key_roles : aws_kms_key.key[k].arn if !contains(rs, each.key)] }],
+    [{ Effect = "Deny", Action = ["logs:CreateLogStream", "logs:PutLogEvents"], Resource = [for k, g in aws_cloudwatch_log_group.log : "${g.arn}:*" if k != local.role_log[each.key]] }],
+    each.key != "scheduler" ? [{ Effect = "Allow", Action = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"], Resource = ["${aws_cloudwatch_log_group.log[local.role_log[each.key]].arn}:*"] }] : [],
+    contains(["ecs_task", "projector", "relay", "archiver"], each.key) ? [{ Effect = "Allow", Action = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"], Resource = [for k, rs in local.key_roles : aws_kms_key.key[k].arn if contains(rs, each.key)] }] : [],
+    contains(["ecs_task", "relay"], each.key) ? [
+      { Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = local.sqs_actions, Resource = [aws_sqs_queue.dlq.arn] }
+    ] : [],
+    each.key == "projector" ? [
+      { Effect = "Allow", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Allow", Action = ["sqs:SendMessage"], Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = ["sqs:SendMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.dlq.arn] }
+    ] : [],
+    contains(["ecs_execution", "archiver", "scheduler"], each.key) ? [{ Effect = "Deny", Action = local.sqs_actions, Resource = local.queues }] : [],
+    each.key == "ecs_task" ? [
+      { Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"], Resource = local.ddb },
+      { Effect = "Deny", Action = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = [aws_dynamodb_table.main.arn] }
+    ] : [],
+    each.key == "projector" ? [
+      { Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"], Resource = local.ddb },
+      { Effect = "Deny", Action = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = [aws_dynamodb_table.main.arn] }
+    ] : [],
+    contains(["ecs_execution", "relay", "archiver", "scheduler"], each.key) ? [{ Effect = "Deny", Action = local.ddb_actions, Resource = local.ddb }] : [],
+    each.key == "archiver" ? [
+      { Effect = "Allow", Action = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"], Resource = ["${aws_s3_bucket.audit.arn}/ledger-audit/*"] },
+      { Effect = "Allow", Action = ["s3:ListBucket", "s3:GetBucketLocation"], Resource = [aws_s3_bucket.audit.arn] },
+      { Effect = "Deny", Action = ["s3:DeleteObject", "s3:DeleteObjectVersion"], Resource = local.s3 }
+    ] : [{ Effect = "Deny", Action = local.s3_actions, Resource = local.s3 }],
+    each.key == "scheduler" ? [
+      { Effect = "Allow", Action = ["lambda:InvokeFunction"], Resource = [local.worker_arns.relay, local.worker_arns.archiver] },
+      { Effect = "Deny", Action = ["lambda:InvokeFunction"], Resource = [local.worker_arns.projector] }
+    ] : []
+  ) })
+}
+resource "aws_sqs_queue_policy" "main" {
+  queue_url = aws_sqs_queue.main.url
+  policy = jsonencode({ Version = "2012-10-17", Statement = [
+    { Effect = "Allow", Principal = { AWS = [local.role_arns.ecs_task, local.role_arns.relay] }, Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = aws_sqs_queue.main.arn },
+    { Effect = "Allow", Principal = { AWS = local.role_arns.projector }, Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"], Resource = aws_sqs_queue.main.arn },
+    { Effect = "Deny", Principal = { AWS = [for r in ["ecs_execution", "projector", "archiver", "scheduler"] : local.role_arns[r]] }, Action = ["sqs:SendMessage"], Resource = aws_sqs_queue.main.arn },
+    { Effect = "Deny", Principal = { AWS = [for r in local.roles : local.role_arns[r] if r != "projector"] }, Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = aws_sqs_queue.main.arn }
+  ] })
+}
+resource "aws_sqs_queue_policy" "dlq" {
+  queue_url = aws_sqs_queue.dlq.url
+  policy = jsonencode({ Version = "2012-10-17", Statement = [
+    { Effect = "Allow", Principal = { AWS = local.role_arns.projector }, Action = ["sqs:SendMessage"], Resource = aws_sqs_queue.dlq.arn },
+    { Effect = "Deny", Principal = { AWS = values(local.role_arns) }, Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = aws_sqs_queue.dlq.arn },
+    { Effect = "Deny", Principal = { AWS = [for r in local.roles : local.role_arns[r] if r != "projector"] }, Action = ["sqs:SendMessage"], Resource = aws_sqs_queue.dlq.arn }
+  ] })
+}
+resource "aws_s3_bucket_policy" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  policy = jsonencode({ Version = "2012-10-17", Statement = [
+    { Effect = "Allow", Principal = { AWS = local.role_arns.archiver }, Action = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"], Resource = "${aws_s3_bucket.audit.arn}/ledger-audit/*" },
+    { Effect = "Allow", Principal = { AWS = local.role_arns.archiver }, Action = ["s3:ListBucket", "s3:GetBucketLocation"], Resource = aws_s3_bucket.audit.arn },
+    { Effect = "Deny", Principal = { AWS = values(local.role_arns) }, Action = ["s3:DeleteObject", "s3:DeleteObjectVersion"], Resource = local.s3 },
+    { Effect = "Deny", Principal = { AWS = [for r in local.roles : local.role_arns[r] if r != "archiver"] }, Action = ["s3:PutObject"], Resource = local.s3 }
+  ] })
+}
*** Add File: /workspace/submission/infra/compute.tf
+locals {
+  database_url = "postgres://${urlencode(local.c.db_username)}:${urlencode(local.c.db_password)}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${local.c.db_name}"
+  valkey_url = "redis://${aws_elasticache_replication_group.main.primary_endpoint_address}:6379"
+  common_env = {
+    AWS_REGION = local.region
+    AWS_DEFAULT_REGION = local.region
+    AWS_ACCESS_KEY_ID = "test"
+    AWS_SECRET_ACCESS_KEY = "test"
+    AWS_ENDPOINT_URL = local.endpoint
+  }
+  worker_env = {
+    projector = { PROJECTION_TABLE = aws_dynamodb_table.main.name, VALKEY_URL = local.valkey_url }
+    relay = { DATABASE_URL = local.database_url, SQS_QUEUE_URL = aws_sqs_queue.main.url, OUTBOX_BATCH_SIZE = "50" }
+    archiver = { DATABASE_URL = local.database_url, AUDIT_BUCKET = aws_s3_bucket.audit.id, AUDIT_PREFIX = "ledger-audit/" }
+  }
+}
+resource "aws_lambda_function" "worker" {
+  for_each = local.worker_env
+  function_name = "${local.p}-${each.key}"
+  role = aws_iam_role.role[each.key].arn
+  package_type = "Image"
+  image_uri = local.c["${each.key}_image"]
+  timeout = 30
+  memory_size = 256
+  image_config {
+    command = []
+    entry_point = []
+  }
+  environment { variables = merge(local.common_env, each.value, { CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.log[each.key].name }) }
+  depends_on = [aws_iam_role_policy.canonical]
+}
+resource "aws_lambda_event_source_mapping" "projector" {
+  event_source_arn = aws_sqs_queue.main.arn
+  function_name = aws_lambda_function.worker["projector"].arn
+  enabled = true
+  batch_size = 5
+  maximum_batching_window_in_seconds = 0
+  function_response_types = ["ReportBatchItemFailures"]
+}
+resource "aws_scheduler_schedule" "worker" {
+  for_each = { relay = "rate(1 minute)", archiver = "rate(5 minutes)" }
+  name = "${local.p}-${each.key}"
+  schedule_expression = each.value
+  state = "ENABLED"
+  flexible_time_window { mode = "OFF" }
+  target {
+    arn = aws_lambda_function.worker[each.key].arn
+    role_arn = aws_iam_role.role["scheduler"].arn
+    input = "{}"
+  }
