+DO $$ DECLARE r RECORD; BEGIN
+ FOR r IN SELECT tgrelid::regclass AS t,tgname FROM pg_trigger
+ WHERE NOT tgisinternal AND tgrelid IN ('clearledger.settlements'::regclass,'clearledger.events'::regclass,'clearledger.outbox'::regclass,'clearledger.idempotency_keys'::regclass) LOOP
